// Writes dist/feather-embed.d.ts: the public types in one file, with the types they use from Feather's own packages
// (intent, context, tokens) inlined, so a consumer needs none of them. No dependencies but TypeScript.
//   1. tsc emits the declarations of src/index.ts into .dts/
//   2. every module reachable from there through a relative import or a Feather package is inlined, dependencies first,
//      with its imports removed and its `export` keywords dropped
//   3. the entry's own exports are written once, at the end
import { spawnSync } from "node:child_process"
import fs from "node:fs"
import path from "node:path"
import { createRequire } from "node:module"

const here = path.dirname(new URL(import.meta.url).pathname)
const pkgDir = path.resolve(here, "..")
const require = createRequire(path.join(pkgDir, "package.json"))
const outDir = path.join(pkgDir, ".dts")

fs.rmSync(outDir, { recursive: true, force: true })
const tsc = spawnSync(process.execPath, [require.resolve("typescript/bin/tsc"), "-p", "tsconfig.dts.json"], { cwd: pkgDir, stdio: "inherit" })
if (tsc.status !== 0) process.exit(tsc.status ?? 1)

const STATEMENT = /^(import|export)\s+(?:type\s+)?([^;]*?)\s*from\s*["']([^"']+)["'];?[ \t]*$/gm

function resolveSpec(spec, from) {
  if (spec.startsWith(".")) {
    const base = path.resolve(path.dirname(from), spec)
    for (const candidate of [base.replace(/\.(m?[jt]sx?)$/, ".d.ts"), base.replace(/\.(m?[jt]sx?)$/, ".d.mts"), `${base}.d.ts`, base]) if (candidate.endsWith(".d.ts") || candidate.endsWith(".d.mts")) if (fs.existsSync(candidate)) return candidate
    throw new Error(`cannot resolve ${spec} from ${from}`)
  }
  if (spec.startsWith("@aleeforoughi/feather-")) {
    const manifest = require.resolve(`${spec}/package.json`)
    const entry = JSON.parse(fs.readFileSync(manifest, "utf8")).exports["."].types
    return path.resolve(path.dirname(manifest), entry)
  }
  throw new Error(`feather-embed's declarations may only import Feather packages; found "${spec}" in ${from}`)
}

const order = []
const seen = new Set()
const exportsOfEntry = []

function visit(file, entry) {
  if (seen.has(file)) return
  seen.add(file)
  let text = fs.readFileSync(file, "utf8")
  const deps = []
  text = text.replace(STATEMENT, (_all, kind, clause, spec) => {
    deps.push(resolveSpec(spec, file))
    if (entry && kind === "export" && !clause.startsWith("*")) exportsOfEntry.push(_all.trim().replace(/\s+from\s*["'][^"']+["'];?$/, "").replace(/^export\s+/, ""))
    return ""
  })
  for (const dep of deps) visit(dep, false)
  text = text
    .replace(/^import\s+["'][^"']+["'];?[ \t]*$/gm, "")
    .replace(/^export\s+declare\s/gm, "declare ")
    .replace(/^export\s+(?=(?:interface|type|const|function|class|enum|abstract)\b)/gm, "")
    .replace(/^export\s+(?:type\s+)?\{[^}]*\};?[ \t]*$/gm, "")
    .replace(/^\/\/# sourceMappingURL=.*$/gm, "")
  order.push({ file, text: text.trim() })
}

visit(path.join(outDir, "index.d.ts"), true)

// Keep only what the public names reach: split every module into top-level declarations (with their doc comments) and
// follow identifiers from the entry's exports.
const DECL = /^(?:declare\s+)?(?:function|const|class|interface|type|enum)\s+(\w+)/
const chunks = new Map()
for (const { file, text } of order) {
  let pending = []
  let current = null
  let inComment = false
  for (const line of text.split("\n")) {
    // A doc comment at column 0 belongs to the declaration after it.
    if (inComment || /^\/\*/.test(line)) {
      pending.push(line)
      inComment = !line.includes("*/")
      continue
    }
    const m = DECL.exec(line)
    if (m) {
      if (chunks.has(m[1])) throw new Error(`${m[1]} is declared in both ${chunks.get(m[1]).file} and ${file}`)
      current = { name: m[1], file, lines: [...pending, line] }
      chunks.set(m[1], current)
      pending = []
    } else if (current) {
      current.lines.push(...pending, line)
      pending = []
    }
  }
}
const wanted = new Set()
const queue = exportsOfEntry.flatMap((clause) => [...clause.matchAll(/(?:^|[{,\s])(?:type\s+)?(\w+)(?=\s*(?:,|\}|$|\s+as\b))/g)].map((m) => m[1]))
while (queue.length) {
  const name = queue.pop()
  if (wanted.has(name) || !chunks.has(name)) continue
  wanted.add(name)
  for (const id of chunks.get(name).lines.join("\n").matchAll(/\b[A-Za-z_]\w*\b/g)) if (chunks.has(id[0]) && !wanted.has(id[0])) queue.push(id[0])
}
const kept = []
for (const { file } of order) for (const c of chunks.values()) if (c.file === file && wanted.has(c.name)) kept.push(c.lines.join("\n").trim())

const header = "// @aleeforoughi/feather-embed: types for the browser bundle (feather-embed.js). Generated by build/bundle-dts.mjs.\n"
const body = kept.join("\n\n")
const reexports = exportsOfEntry.map((clause) => `export ${clause};`)
fs.mkdirSync(path.join(pkgDir, "dist"), { recursive: true })
fs.writeFileSync(path.join(pkgDir, "dist", "feather-embed.d.ts"), `${header}\n${body}\n\n${reexports.join("\n")}\n`)
fs.rmSync(outDir, { recursive: true, force: true })
console.log(`dist/feather-embed.d.ts: ${kept.length} declarations from ${order.length} modules`)
